#!/usr/bin/env python3
"""Build a data-driven Japan trip configurator from data/trip_data.json."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data/trip_data.json"
OUT = ROOT / "outputs/japan-configurator.html"
MD = ROOT / "outputs/japan-configurator.md"


def markdown(data: dict) -> str:
    trip = data['trip']
    lines = [
        '# Japan Trip Configurator', '',
        f"Pracovné termíny: {trip['working_dates']['outbound']} – {trip['working_dates']['return']}", '',
        '## Letecké možnosti', '',
        '| ID | Variant | Trasa | Cena | Stav | Link |', '|---|---|---|---:|---|---|'
    ]
    for f in data['flight_options']:
        price = f"{f['price_total_eur']} €" if f['price_total_eur'] else 'neoverené'
        lines.append(f"| {f['id']} | {f['label']} | {f['origin']} → {f['arrival']} | {price} | {'overené' if f['verified'] else 'čaká na live overenie'} | [otvoriť]({f['search_url']}) |")
    lines += ['', '## Lokácie a POI', '']
    for loc in data['locations']:
        lines += [f"### {loc['name']}", '', f"Noci: {loc['nights']} · Základňa: {loc['stay_area']} · Pešia dostupnosť: {loc['walkability']}", '', f"Počasie: {loc['weather']['temperature_c']} °C; {loc['weather']['rain']} — {loc['weather']['note']} ([zdroj]({loc['weather']['source']}))", '', '| POI | Typ | Čas | Cena | Link |', '|---|---|---:|---:|---|']
        for poi in loc['pois']:
            lines.append(f"| {poi['name']} | {poi['type']} | {poi['time_h']} h | {poi['cost_eur']} € | [mapa]({poi['map']}) · [info]({poi['link']}) |")
        lines.append('')
    lines += ['## Presuny', '', '| Odkiaľ | Kam | Spôsob | Čas | Cena | Nákup |', '|---|---|---|---|---:|---|']
    for t in data['transfers']:
        lines.append(f"| {t['from']} | {t['to']} | {t['mode']} | {t['duration']} | {t['cost_eur']} € | [kúpiť/info]({t['buy']}) |")
    lines += ['', '## Poznámka k cenám', '', 'Ceny označené ako odhad treba overiť pri nákupe. Live ceny leteniek sa do konfigurátora doplnia po uložení overeného pozorovania pre všetkých 5 cestujúcich.']
    return '\n'.join(lines) + '\n'


def build() -> str:
    data = json.loads(DATA.read_text(encoding='utf-8'))
    payload = json.dumps(data, ensure_ascii=False).replace('</script>', '<\\/script>')
    html = '''<!doctype html><html lang="sk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Japan 2026 · Interactive Trip Configurator</title>
<style>
:root{{--bg:#f4f1eb;--ink:#14212b;--muted:#6d7a83;--card:#fff;--line:#dfe2dd;--red:#c84452;--blue:#245b75;--gold:#d79c3f;--shadow:0 16px 45px #14212b14}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Inter,system-ui,sans-serif}}a{{color:var(--blue)}}.wrap{{max-width:1240px;margin:auto;padding:0 22px}}header{{color:#fff;background:linear-gradient(120deg,#102d3aee,#562c3fdd),url('https://images.unsplash.com/photo-1524413840807-0c3cb6fa808d?auto=format&fit=crop&w=2200&q=85') center/cover;padding:72px 0 58px}}.eyebrow{{color:var(--gold);font-size:.72rem;font-weight:900;letter-spacing:.14em;text-transform:uppercase}}h1{{font-size:clamp(2.8rem,7vw,6.8rem);line-height:.9;letter-spacing:-.07em;margin:16px 0;max-width:900px}}h2{{font-size:2rem;letter-spacing:-.05em;margin:0 0 18px}}h3{{margin:5px 0 8px}}.lead{{font-size:1.1rem;max-width:690px;color:#e8eef1}}.toolbar{{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}.button,button,select{{font:inherit}}.button{{display:inline-block;border:0;border-radius:999px;background:var(--red);color:#fff;text-decoration:none;padding:11px 17px;font-weight:800;cursor:pointer}}.button.alt{{background:#ffffff20;border:1px solid #ffffff66}}main{{padding:30px 0 80px}}.layout{{display:grid;grid-template-columns:350px 1fr;gap:22px;align-items:start}}.sidebar,.panel,.card{{background:var(--card);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow)}}.sidebar{{padding:20px;position:sticky;top:15px}}.sidebar h3{{margin-top:22px}}label.option{{display:flex;gap:10px;align-items:flex-start;padding:10px;border:1px solid var(--line);border-radius:12px;margin:7px 0;cursor:pointer}}label.option:hover{{border-color:var(--red)}}label.option input{{accent-color:var(--red);margin-top:4px}}label.option small{{display:block;color:var(--muted)}}select{{width:100%;padding:11px;border:1px solid var(--line);border-radius:10px;background:#fff}}.content{{min-width:0}}.summary{{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:22px}}.metric{{background:var(--ink);color:#fff;border-radius:16px;padding:15px}}.metric b{{font-size:1.65rem;display:block}}.metric span{{color:#bbcbd3;font-size:.8rem}}.notice{{background:#fff5db;border:1px solid #ecd28c;padding:13px 16px;border-radius:14px;margin:16px 0;color:#6c5323}}.section-title{{display:flex;justify-content:space-between;align-items:end;gap:15px;margin:32px 0 14px}}.muted{{color:var(--muted)}}.cards{{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}}.card{{padding:19px}}.flight-card{{border-left:5px solid var(--red)}}.price{{font-size:1.8rem;letter-spacing:-.05em}}.price small{{font-size:.75rem;color:var(--muted);letter-spacing:0}}.chips{{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}}.chip{{border-radius:999px;background:#edf0ed;padding:4px 9px;font-size:.78rem;color:#40515b}}.location{{overflow:hidden}}.location-top{{display:flex;justify-content:space-between;gap:12px}}.location-top img{{width:120px;height:90px;object-fit:cover;border-radius:12px}}.poi-list,.activity-list{{display:grid;gap:7px;margin-top:14px}}.poi,.activity{{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;padding:10px;background:#faf9f6;border-radius:10px}}.poi b,.activity b{{display:block}}.poi small,.activity small{{color:var(--muted)}}.poi .links,.activity .links{{text-align:right;white-space:nowrap;font-size:.78rem}}.transfer{{display:grid;grid-template-columns:1fr 1fr 1.4fr .7fr .8fr auto;gap:8px;align-items:center;padding:13px 12px;border-bottom:1px solid var(--line)}}.transfer:first-child{{font-weight:800;background:#eef2f0}}.transfer:not(:first-child){{font-size:.9rem}}.route-strip{{display:flex;gap:0;overflow:auto;margin:15px 0 24px}}.route-stop{{min-width:150px;padding:13px;background:#fff;border:1px solid var(--line);position:relative}}.route-stop:first-child{{border-radius:14px 0 0 14px}}.route-stop:last-child{{border-radius:0 14px 14px 0}}.route-stop:not(:last-child):after{{content:'→';position:absolute;right:-12px;top:20px;z-index:2;background:var(--gold);border-radius:50%;width:24px;height:24px;text-align:center}}.route-stop b{{display:block}}.route-stop small{{color:var(--muted)}}.footer{{background:var(--ink);color:#c3d0d5;padding:35px 0}}.footer a{{color:#fff}}@media(max-width:900px){{.layout{{grid-template-columns:1fr}}.sidebar{{position:static}}.summary{{grid-template-columns:repeat(2,1fr)}}.cards{{grid-template-columns:1fr}}.transfer{{grid-template-columns:1fr 1fr 1fr}}.transfer a{{grid-column:span 3}}}}@media(max-width:560px){{.wrap{{padding:0 14px}}.summary{{grid-template-columns:1fr 1fr}}.route-stop{{min-width:130px}}}}
</style></head><body><header><div class="wrap"><div class="eyebrow">Japan · configurator 2026</div><h1>Vyber cestu.<br>Postav si deň.</h1><p class="lead">Interaktívny plánovač pre 5 ľudí: vyber letenku, lokácie a aktivity. Trasa, noci, odhady cien, počasie, POI a mapy sa prepočítajú okamžite.</p><div class="toolbar"><a class="button" href="#config">Začať konfiguráciu ↓</a><a class="button alt" href="japan-configurator.md">Markdown verzia ↗</a><a class="button alt" href="japan-trip-planner.pdf">PDF základný plán ↗</a></div></div></header><main id="config"><div class="wrap layout"><aside class="sidebar"><div class="eyebrow">1 · Letenka</div><h3>Vyber prílet a odlet</h3><select id="flightSelect"></select><div id="flightInfo" class="notice"></div><h3>2 · Lokácie</h3><p class="muted">Aspoň Tokio/Kjóto/Osaka. Okinawa je voliteľná.</p><div id="locationChoices"></div><h3>3 · Aktivity</h3><p class="muted">Vyber aktivity; cena a čas sa pripočítajú k návrhu.</p><div id="activityChoices"></div><button class="button" id="reset">Resetovať výber</button></aside><section class="content"><div class="summary"><div class="metric"><b id="metricNights">0</b><span>nocí</span></div><div class="metric"><b id="metricStops">0</b><span>presunov</span></div><div class="metric"><b id="metricHours">0 h</b><span>vybrané aktivity</span></div><div class="metric"><b id="metricCost">0 €</b><span>odhad extra/os.</span></div></div><div class="notice"><b>Live ceny:</b> všetky aktuálne ceny leteniek sa musia overiť pri checkout-e. Neoverené varianty sú jasne označené; po uložení pozorovania sa zobrazí konkrétna suma pre 5 cestujúcich.</div><div class="section-title"><div><div class="eyebrow">Výsledná trasa</div><h2 id="routeTitle">Vyber možnosti</h2></div><a id="routeMap" class="button" target="_blank" rel="noopener">Otvoriť mapu trasy ↗</a></div><div id="routeStrip" class="route-strip"></div><div class="section-title"><div><div class="eyebrow">Letecké možnosti</div><h2>Porovnanie</h2></div></div><div id="flightCards" class="cards"></div><div class="section-title"><div><div class="eyebrow">Lokácie</div><h2>Čo uvidíte</h2></div><span class="muted">Klikni na mapu alebo info</span></div><div id="locationCards" class="cards"></div><div class="section-title"><div><div class="eyebrow">Presuny</div><h2>Koľko trvá Japonsko</h2></div></div><div class="panel" id="transferTable"></div><div class="section-title"><div><div class="eyebrow">Praktické poznámky</div><h2>Predpoveď, chôdza, nákup</h2></div></div><div class="cards"><div class="card"><h3>Počasie</h3><p class="muted">Zobrazené údaje sú historické klimatické odhady pre obdobie cesty, nie konkrétna predpoveď. Konkrétnu predpoveď treba skontrolovať približne 7–10 dní pred presunom.</p><a href="https://www.japan.travel/en/uk/plan/weather/" target="_blank">JNTO weather info ↗</a></div><div class="card"><h3>Presuny a chôdza</h3><p class="muted">V mestách rátaj typicky s 5–15 minútami chôdze na jednu atrakciu; pri rodičoch je výhodnejšie bývanie do 8–10 minút od stanice a občasný taxík než hotel ďaleko od centra.</p><a href="https://www.google.com/maps" target="_blank">Google Maps ↗</a></div></div></section></div></main><footer class="footer"><div class="wrap"><b>Japan Trip Configurator</b><p>Generované z <code>data/trip_data.json</code>. Výstupy: HTML, Markdown, PDF.</p><a href="../README.md">README</a> · <a href="../docs/accommodation.md">Ubytovanie</a> · <a href="../docs/flight-options.md">Lety</a></div></footer>
<script>const DATA=__PAYLOAD__;const imgs={{tokyo:'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=500&q=80',kanazawa:'https://images.unsplash.com/photo-1528360983277-13d401cdc186?auto=format&fit=crop&w=500&q=80',kyoto:'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=500&q=80',osaka:'https://images.unsplash.com/photo-1590559899731-a382839e5549?auto=format&fit=crop&w=500&q=80',okinawa:'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=500&q=80'}};const flightSelect=document.querySelector('#flightSelect'),flightInfo=document.querySelector('#flightInfo'),locChoices=document.querySelector('#locationChoices'),actChoices=document.querySelector('#activityChoices');let state={{flight:'f1',locations:['tokyo','kanazawa','kyoto','osaka'],activities:[]}};const euro=n=>n.toLocaleString('sk-SK')+' €';function getFlight(){{return DATA.flight_options.find(x=>x.id===state.flight)}}function getLocs(){{return state.locations.map(id=>DATA.locations.find(x=>x.id===id)).filter(Boolean)}}function renderChoices(){{flightSelect.innerHTML=DATA.flight_options.map(f=>`<option value="${{f.id}}">${{f.label}}</option>`).join('');flightSelect.value=state.flight;flightInfo.innerHTML=(()=>{{let f=getFlight();return `<b>${{f.origin}} → ${{f.arrival}}</b><br>${{f.departure_date}} → ${{f.return_date}}<br><small>${{f.price_total_eur?euro(f.price_total_eur):f.price_note}}</small><br><a href="${{f.search_url}}" target="_blank">Otvoriť vyhľadávanie ↗</a>`}})();locChoices.innerHTML=DATA.locations.map(l=>`<label class="option"><input type="checkbox" data-location="${{l.id}}" ${{state.locations.includes(l.id)?'checked':''}}><span><b>${{l.name}}</b><small>${{l.nights}} noci · ${{l.best_for.join(' · ')}}</small></span></label>`).join('');actChoices.innerHTML=getLocs().flatMap(l=>l.activities.map((a,i)=>`<label class="option"><input type="checkbox" data-activity="${{l.id}}:${{i}}" ${{state.activities.includes(l.id+':'+i)?'checked':''}}><span><b>${{a.name}}</b><small>${{l.name}} · ${{a.hours}} h · cca ${{a.cost_eur}} €</small></span></label>`)).join('');document.querySelectorAll('[data-location]').forEach(x=>x.addEventListener('change',()=>{{state.locations=[...document.querySelectorAll('[data-location]:checked')].map(y=>y.dataset.location);if(state.locations.length<3){{x.checked=true;return}}render()}}));document.querySelectorAll('[data-activity]').forEach(x=>x.addEventListener('change',()=>{{state.activities=[...document.querySelectorAll('[data-activity]:checked')].map(y=>y.dataset.activity);render()}}))}}function render(){{renderChoices();let f=getFlight(),locs=getLocs(),acts=state.activities.map(k=>{{let [id,i]=k.split(':');let l=DATA.locations.find(x=>x.id===id);return l.activities[Number(i)]}});let nights=locs.reduce((s,l)=>s+l.nights,0);let transfers=Math.max(locs.length-1,0);let hours=acts.reduce((s,a)=>s+a.hours,0);let extra=acts.reduce((s,a)=>s+a.cost_eur,0);document.querySelector('#metricNights').textContent=nights;document.querySelector('#metricStops').textContent=transfers;document.querySelector('#metricHours').textContent=hours+' h';document.querySelector('#metricCost').textContent=euro(extra);document.querySelector('#routeTitle').textContent=(f.arrival==='OSA'?'Osaka':'Tokyo')+' → '+locs.map(l=>l.name).join(' → ')+' → '+(f.departure_city||'Tokyo');document.querySelector('#routeMap').href='https://www.google.com/maps/dir/'+locs.map(l=>encodeURIComponent(l.name)).join('/');document.querySelector('#routeStrip').innerHTML=locs.map(l=>`<div class="route-stop"><b>${{l.name}}</b><small>${{l.nights}} noci<br>${{l.stay_area}}</small></div>`).join('');document.querySelector('#flightCards').innerHTML=DATA.flight_options.map(x=>`<article class="card flight-card"><div class="eyebrow">${{x.origin}} → ${{x.arrival}}</div><h3>${{x.label}}</h3><div class="price">${{x.price_total_eur?euro(x.price_total_eur):'Cena na overenie'}} <small>${{x.price_total_eur?'za 5 ľudí':'live dáta chýbajú'}}</small></div><p>${{x.departure_date}} → ${{x.return_date}} · ${{x.stops}} · ${{x.route_effect}}</p><div class="chips"><span class="chip">príručná batožina</span><span class="chip">5 osôb</span><span class="chip">${{x.verified?'overené':'neoverené'}}</span></div><a class="button" href="${{x.search_url}}" target="_blank">Vyhľadať ponuku ↗</a></article>`).join('');document.querySelector('#locationCards').innerHTML=locs.map(l=>`<article class="card location"><div class="location-top"><div><div class="eyebrow">${{l.nights}} noci · ${{l.stay_area}}</div><h3>${{l.name}}</h3><p class="muted">${{l.best_for.join(' · ')}}</p></div><img src="${{imgs[l.id]||imgs.tokyo}}" alt="${{l.name}}"></div><p><b>Historické počasie:</b> ${{l.weather.temperature_c}} °C · ${{l.weather.rain}}. <a href="${{l.weather.source}}" target="_blank">zdroj ↗</a></p><div class="poi-list">${{l.pois.map(p=>`<div class="poi"><span><b>${{p.name}}</b><small>${{p.type}} · ${{p.time_h}} h · ${{p.cost_eur}} €<br>${{p.tip}}</small></span><span class="links"><a href="${{p.map}}" target="_blank">mapa</a><br><a href="${{p.link}}" target="_blank">info</a></span></div>`).join('')}}</div></article>`).join('');let selected=new Set(locs.map(l=>l.name));document.querySelector('#transferTable').innerHTML='<div class="transfer"><span>Odkiaľ</span><span>Kam</span><span>Spôsob</span><span>Čas</span><span>Cena</span><span>Odkaz</span></div>'+DATA.transfers.filter(t=>selected.has(t.from)||selected.has(t.to)||t.from==='Japan').map(t=>`<div class="transfer"><b>${{t.from}}</b><b>${{t.to}}</b><span>${{t.mode}}</span><span>${{t.duration}}</span><span>${{t.cost_eur}} €</span><a href="${{t.buy}}" target="_blank">kúpiť ↗</a></div>`).join('')}}flightSelect.addEventListener('change',()=>{{state.flight=flightSelect.value;render()}});document.querySelector('#reset').addEventListener('click',()=>{{state={{flight:'f1',locations:['tokyo','kanazawa','kyoto','osaka'],activities:[]}};render()}});render();</script></body></html>'''
    return html.replace('{{', '{').replace('}}', '}').replace('__PAYLOAD__', payload)


if __name__ == '__main__':
    OUT.parent.mkdir(parents=True, exist_ok=True)
    md_text = markdown(json.loads(DATA.read_text(encoding='utf-8')))
    MD.write_text(md_text, encoding='utf-8')
    try:
        try:
            from src.build_pdf import build_pdf_bytes
        except ModuleNotFoundError:
            from build_pdf import build_pdf_bytes
        (ROOT / 'outputs/japan-configurator.pdf').write_bytes(build_pdf_bytes(md_text))
    except ModuleNotFoundError:
        # The HTML and Markdown remain usable without the optional PDF dependency.
        pass
    print(OUT)
    print(MD)
